/// <summary>
/// MPJ_11539 - kscerri - 27/07/2021
/// Class <c>METPrintMgmtReportFormatPopulatorAppSuite_Extension</c> populates the PrintMgmtReportFormat table used for print management 
/// with the documents.
/// </summary>
[ExtensionOf(classStr(PrintMgmtReportFormatPopulator))]
public final class METPrintMgmtReportFormatPopulatorAppSuite_Extension
{
    #ISOCountryRegionCodes
    #PrintMgmtSetup

}

Method.Source:
    /// <summary>
    /// MPJ_11539 - kscerri - 27/07/2021
    /// adds documents
    /// </summary>
    protected void addDocuments()
    {
        this.customAddSalesDocuments();
        this.customAddPurchDocuments();

        next addDocuments();
    }

    /// <summary>
    /// MPJ_11539 - kscerri - 27/07/2021
    /// Adds sales records to the PrintMgmtReportFormat table.
    /// </summary>
    private void customAddSalesDocuments()
    {
        //Use this method as we need the Fifth parameter "PrintMgmtReportFormatSystem" = True for Accountable documents that are configured in Print Management.
        //If its missing then we can get "Report name in report contract cannot be null or empty." errors on reprints
        PrintMgmtDelegatesHandler::add(PrintMgmtDocumentType::METCustActivityStatement, ssrsReportStr(METCustActivityStatement, Report), ssrsReportStr(METCustActivityStatement, Report), #NoCountryRegionId, true);
        
        //MPJ_15231_Customer Statement DCP 17/05/2022
        PrintMgmtDelegatesHandler::add(PrintMgmtDocumentType::METCustActivityStatementMulti, ssrsReportStr(METCustActivityStatement, ReportMulti), ssrsReportStr(METCustActivityStatement, ReportMulti), #NoCountryRegionId, true);

        
        //MPJ_31513 Invoicing Design
        PrintMgmtDelegatesHandler::add(PrintMgmtDocumentType::SalesOrderInvoice, ssrsReportStr(METSalesInvoice, MFG), ssrsReportStr(METSalesInvoice, MFG), #NoCountryRegionId, true);
        PrintMgmtDelegatesHandler::add(PrintMgmtDocumentType::SalesOrderInvoice, ssrsReportStr(METSalesInvoice, CCC), ssrsReportStr(METSalesInvoice, CCC), #NoCountryRegionId, true);
        PrintMgmtDelegatesHandler::add(PrintMgmtDocumentType::SalesOrderInvoice, ssrsReportStr(METSalesInvoice, CSD), ssrsReportStr(METSalesInvoice, CSD), #NoCountryRegionId, true);
        PrintMgmtDelegatesHandler::add(PrintMgmtDocumentType::SalesOrderInvoice, ssrsReportStr(METSalesInvoice, ALM), ssrsReportStr(METSalesInvoice, ALM), #NoCountryRegionId, true);
        PrintMgmtDelegatesHandler::add(PrintMgmtDocumentType::SalesOrderInvoice, ssrsReportStr(METSalesInvoice, IHG), ssrsReportStr(METSalesInvoice, IHG), #NoCountryRegionId, true);

    }

    /// <summary>
    /// //MPJ_31513 Invoicing Design DCP 07/09/2022
    /// Adds purch records to the PrintMgmtReportFormat table.
    /// </summary>
    private void customAddPurchDocuments()
    {
        // MPJ_17952_PBMSReports1
        PrintMgmtDelegatesHandler::add(PrintMgmtDocumentType::PurchaseOrderConfirmationRequest, ssrsReportStr(METPurchPurchaseOrder, Food), ssrsReportStr(METPurchPurchaseOrder, Food), #NoCountryRegionId, true);
        PrintMgmtDelegatesHandler::add(PrintMgmtDocumentType::PurchaseOrderConfirmationRequest, ssrsReportStr(METPurchPurchaseOrder, Hardware), ssrsReportStr(METPurchPurchaseOrder, Hardware), #NoCountryRegionId, true);
        PrintMgmtDelegatesHandler::add(PrintMgmtDocumentType::PurchaseOrderConfirmationRequest, ssrsReportStr(METPurchPurchaseOrder, Liquor), ssrsReportStr(METPurchPurchaseOrder, Liquor), #NoCountryRegionId, true);

        PrintMgmtDelegatesHandler::add(PrintMgmtDocumentType::PurchaseOrderRequisition, ssrsReportStr(METPurchPurchaseOrder, Food), ssrsReportStr(METPurchPurchaseOrder, Food), #NoCountryRegionId, true);
        PrintMgmtDelegatesHandler::add(PrintMgmtDocumentType::PurchaseOrderRequisition, ssrsReportStr(METPurchPurchaseOrder, Hardware), ssrsReportStr(METPurchPurchaseOrder, Hardware), #NoCountryRegionId, true);
        PrintMgmtDelegatesHandler::add(PrintMgmtDocumentType::PurchaseOrderRequisition, ssrsReportStr(METPurchPurchaseOrder, Liquor), ssrsReportStr(METPurchPurchaseOrder, Liquor), #NoCountryRegionId, true);
    }
